public static Long parseOrNull(String str) {
    if (str == null || str.isEmpty()) {
        return null;
    }
    try {
        return Instant.parse(str).toEpochMilli();
    } catch (Throwable ex) {
        logger.debug(String.format("Failed to parse datetime: %s", str), ex);
        return null;
    }
}
